import{_ as e}from"./chunks/第一步-03.D7lAR9Hu.js";import{_ as o}from"./chunks/发起转账.CTPkJlt5.js";import{_ as r,o as t,c as l,a2 as d}from"./chunks/framework.CqGPl1zp.js";const i="/newx-doc/assets/%E7%BB%9F%E4%B8%80%E6%8E%A5%E5%85%A5.ByeIMQuZ.png",n="/newx-doc/assets/PayClient%E7%B1%BB%E5%9B%BE.D7K9rVff.png",p="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-01.BShXzr6D.png",c="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-02.Bk_rhrPx.png",s="/newx-doc/assets/%E7%AC%AC%E4%BA%8C%E6%AD%A5-%E8%A1%A8%E7%BB%93%E6%9E%84.P_aj-m4K.png",u="/newx-doc/assets/%E7%AC%AC%E4%B8%89%E6%AD%A5-01.BSAVhtcr.png",m="/newx-doc/assets/%E7%AC%AC%E5%9B%9B%E6%AD%A5-01.Dbuz2_9Z.png",h="/newx-doc/assets/%E8%8F%9C%E5%8D%95-%E5%BA%94%E7%94%A8%E4%BF%A1%E6%81%AF.C33Lx-Ld.png",y="/newx-doc/assets/%E6%94%AF%E4%BB%98%E5%BA%94%E7%94%A8.Cnw5wsrJ.png",_="/newx-doc/assets/%E6%94%AF%E4%BB%98%E6%B8%A0%E9%81%93.B4XtYwnr.png",b="/newx-doc/assets/%E6%94%AF%E4%BB%98%E8%AE%A2%E5%8D%95.BBNkUZ5P.png",f="/newx-doc/assets/%E9%80%80%E6%AC%BE%E8%AE%A2%E5%8D%95.4DE_kzxu.png",g="/newx-doc/assets/%E5%9B%9E%E8%B0%83%E9%80%9A%E7%9F%A5.C4_W6Kf8.png",E="/newx-doc/assets/%E5%9B%9E%E8%B0%83%E6%B5%81%E7%A8%8B.KBQmi0xd.png",A="/newx-doc/assets/%E9%85%8D%E7%BD%AE%E5%9B%9E%E8%B0%83%E5%9C%B0%E5%9D%80Boot.CuCGkRUo.png",B="/newx-doc/assets/%E6%8E%A5%E5%85%A5%E7%A4%BA%E4%BE%8B.DXa4k5Q0.png",v="/newx-doc/assets/%E8%BD%AC%E8%B4%A6%E8%AE%A2%E5%8D%95.BM6RRxLs.png",S=JSON.parse('{"title":"功能开启","description":"","frontmatter":{},"headers":[],"relativePath":"pay/build.md","filePath":"pay/build.md","lastUpdated":null}'),k={name:"pay/build.md"};function x(P,a,q,C,w,j){return t(),l("div",null,[...a[0]||(a[0]=[d('<h1 id="功能开启" tabindex="-1">功能开启 <a class="header-anchor" href="#功能开启" aria-label="Permalink to &quot;功能开启&quot;">​</a></h1><p>项目提供统一的支付中心，提供微信、支付宝等支付渠道的支付、退款等能力，方便业务模块进行快速接入，无需关注各种繁琐的支付 API。</p><p><img src="'+i+'" alt="统一接入"></p><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p>它由如下 3 部分组成：</p><p>① <a href="https://github.com/YunaiV/ruoyi-vue-pro/tree/master/yudao-module-pay/src/main/java/cn/iocoder/yudao/module/pay/framework/pay/core/client" target="_blank" rel="noreferrer">支付 SDK 组件</a> ：对接微信、支付宝等支付，提供统一的 PayClient 支付客户端。</p><p><img src="'+n+'" alt="PayClient 类图"></p><p>② <a href="https://github.com/YunaiV/ruoyi-vue-pro/tree/master/yudao-module-pay" target="_blank" rel="noreferrer"><code>yudao-module-pay</code></a> 后端模块：实现支付中心的后端功能，包括支付、退款等能力。</p><ul><li>基于 PayClient 支付客户端，对接微信、支付宝等支付渠道。</li><li>对内提供 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-pay/src/main/java/cn/iocoder/yudao/module/pay/api/order/PayOrderApi.java" target="_blank" rel="noreferrer">PayOrderApi</a> 统一支付 API 能力、<a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-pay/src/main/java/cn/iocoder/yudao/module/pay/api/refund/PayRefundApi.java" target="_blank" rel="noreferrer">PayRefundApi</a> 统一退款 API 能力。</li></ul><p>③ 支付中心的前端，提供支付中心的管理后台，可进行支付渠道的配置、支付订单、退款单的查看等操作。</p><ul><li>Vue2 版本：<a href="https://github.com/yudaocode/yudao-ui-admin-vue2/tree/master/src/views/pay" target="_blank" rel="noreferrer"><code>@/views/pay</code></a> 目录</li><li>Vue3 版本：<a href="https://github.com/yudaocode/yudao-ui-admin-vue3/tree/master/src/views/pay" target="_blank" rel="noreferrer"><code>@/views/pay</code></a> 目录</li></ul><h2 id="_2-功能开启" tabindex="-1">2. 功能开启 <a class="header-anchor" href="#_2-功能开启" aria-label="Permalink to &quot;2. 功能开启&quot;">​</a></h2><p>考虑到编译速度，默认 <code>yudao-module-pay</code> 模块是关闭的，需要手动开启。步骤如下：</p><ul><li>第一步，开启 <code>yudao-module-pay</code> 模块</li><li>第二步，导入支付的 SQL 数据库脚本</li><li>第三步，重启后端项目，确认功能是否生效</li><li>第四步，开启支付相关的 Job 任务</li></ul><h3 id="_2-1-开启-yudao-module-pay-模块" tabindex="-1">2.1 开启 yudao-module-pay 模块 <a class="header-anchor" href="#_2-1-开启-yudao-module-pay-模块" aria-label="Permalink to &quot;2.1 开启 yudao-module-pay 模块&quot;">​</a></h3><p>① 修改根目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，取消 <code>yudao-module-pay</code> 模块的注释。如下图所示：</p><p><img src="'+p+'" alt="取消  模块的注释"></p><p>② 修改 <code>yudao-server</code> 目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-server/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，引入 <code>yudao-module-pay</code> 模块。如下图所示：</p><p><img src="'+c+'" alt="引入  模块"></p><p>③ 点击 IDEA 右上角的【Reload All Maven Projects】，刷新 Maven 依赖。如下图所示：</p><p><img src="'+e+'" alt="刷新 Maven 依赖"></p><h3 id="_2-2-第二步-导入-sql" tabindex="-1">2.2 第二步，导入 SQL <a class="header-anchor" href="#_2-2-第二步-导入-sql" aria-label="Permalink to &quot;2.2 第二步，导入 SQL&quot;">​</a></h3><p>点击 <a href="https://lwb8832652.github.io/newx-doc/sql/pay.sql" target="_blank" rel="noreferrer">下载 SQL</a> 直接下载 SQL 文件，导入到数据库中。</p><p>友情提示：↑↑↑ pay.sql 是可以点击下载的！ ↑↑↑</p><p>重要说明：该 SQL 仅芋道星球成员可使用和商用，否则视为侵权（索赔 100 万，永久追溯）【下载即视为同意】。</p><p><img src="'+s+'" alt="表结构"></p><h3 id="_2-3-第三步-重启项目" tabindex="-1">2.3 第三步，重启项目 <a class="header-anchor" href="#_2-3-第三步-重启项目" aria-label="Permalink to &quot;2.3 第三步，重启项目&quot;">​</a></h3><p>重启后端项目，然后访问前端的支付菜单，确认功能是否生效。如下图所示：</p><p><img src="'+u+'" alt="确认功能是否生效"></p><p>至此，我们就成功开启了支付的功能 🙂</p><h3 id="_2-4-第四步-开启支付-job" tabindex="-1">2.4 第四步，开启支付 Job <a class="header-anchor" href="#_2-4-第四步-开启支付-job" aria-label="Permalink to &quot;2.4 第四步，开启支付 Job&quot;">​</a></h3><p>① 参考 <a href="./../job">《定时任务》</a> 文档，将 Job 定时任务开启。</p><p>② 将 <code>pay</code> 开头的定时都进行开启，例如说：<code>payNotifyJob</code>、<code>payOrderSyncJob</code>、<code>payOrderExpireJob</code>、<code>payRefundSyncJob</code>、<code>payTransferSyncJob</code>。如下图所示：</p><p><img src="'+m+'" alt="开启 Job 任务"></p><h2 id="_3-功能介绍" tabindex="-1">3. 功能介绍 <a class="header-anchor" href="#_3-功能介绍" aria-label="Permalink to &quot;3. 功能介绍&quot;">​</a></h2><h3 id="_3-1-应用信息" tabindex="-1">3.1 应用信息 <a class="header-anchor" href="#_3-1-应用信息" aria-label="Permalink to &quot;3.1 应用信息&quot;">​</a></h3><p>对应 [支付管理 -&gt; 应用信息] 菜单，进行支付渠道、支付应用的管理。如下图所示：</p><p><img src="'+h+'" alt="支付管理 -&gt; 应用信息"></p><h4 id="_3-1-1-支付应用" tabindex="-1">3.1.1 支付应用 <a class="header-anchor" href="#_3-1-1-支付应用" aria-label="Permalink to &quot;3.1.1 支付应用&quot;">​</a></h4><p>每个要接入支付中心的业务，对应一个支付应用。例如说：商城订单算一个应用，预约订单算一个应用。</p><p>点击【新增】按钮，可以进行支付应用的配置，保存在 <code>pay_app</code> 表。如下图所示：</p><p><img src="'+y+'" alt="支付应用"></p><ul><li>应用标识：每个接入支付中心的应用（业务）标识，例如说现有项目中的商城订单使用 <code>mall</code>、会员钱包使用 <code>wallet</code></li><li>支付结果的回调地址：每个业务需要实现一个支付回调接口，在用户支付成功时，支付中心会进行回调。<a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-pay/src/main/java/cn/iocoder/yudao/module/pay/controller/admin/demo/PayDemoOrderController.java#L50-L58" target="_blank" rel="noreferrer">示例订单的支付回调</a> 、<a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mall/yudao-module-trade/src/main/java/cn/iocoder/yudao/module/trade/controller/app/order/AppTradeOrderController.java#L64-L70" target="_blank" rel="noreferrer">商城订单的支付回调</a></li><li>退款结果的回调地址：每个业务需要实现一个退款回调接口，在用户退款成功时，支付中心会进行回调。<a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-pay/src/main/java/cn/iocoder/yudao/module/pay/controller/admin/demo/PayDemoOrderController.java#L68-L76" target="_blank" rel="noreferrer">示例订单的退款回调</a> 、<a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mall/yudao-module-trade/src/main/java/cn/iocoder/yudao/module/trade/controller/admin/aftersale/AfterSaleController.java#L134" target="_blank" rel="noreferrer">商城订单的退款回调</a></li><li>转账结果的回调地址：每个业务需要实现一个退款回调接口，在用户退款成功时，支付中心会进行回调。<a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master-jdk17/yudao-module-pay/src/main/java/cn/iocoder/yudao/module/pay/controller/admin/demo/PayDemoWithdrawController.java#L54-L61" target="_blank" rel="noreferrer">示例提现单的转账回调</a> 、<a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master-jdk17/yudao-module-mall/yudao-module-trade/src/main/java/cn/iocoder/yudao/module/trade/controller/admin/brokerage/BrokerageWithdrawController.java#L85-L93" target="_blank" rel="noreferrer">商城分销提现的转账回调</a></li></ul><p>为什么要有支付应用？直接配置支付渠道不行吗？</p><ol><li>一个系统中，可能有多个业务需要，每个业务的支付、退款回调地址不同。</li><li>同时，每个业务的订单编号可能重复，需要使用支付应用进行隔离，只要求在每个支付应用下保持唯一即可。</li><li>另外，每个业务可能想要配置不同的支付渠道。</li></ol><h4 id="_3-1-2-支付渠道" tabindex="-1">3.1.2 支付渠道 <a class="header-anchor" href="#_3-1-2-支付渠道" aria-label="Permalink to &quot;3.1.2 支付渠道&quot;">​</a></h4><p>每个支付应用下，可以配置多个支付渠道。例如说：这里“示例应用”就配置了支付宝 PC 网站支付、支付宝 Wap 网站支付等等。</p><p>点击【√】或者【×】图标，可以进行支付应用的配置，保存在 <code>pay_channel</code> 表。如下图所示：</p><p><img src="'+_+'" alt="支付渠道"></p><p>支付费率？</p><p>参见 <a href="https://zhuanlan.zhihu.com/p/352559274" target="_blank" rel="noreferrer">《第三方支付的费率、限额、通道分析》</a> 文档。</p><h3 id="_3-2-支付订单" tabindex="-1">3.2 支付订单 <a class="header-anchor" href="#_3-2-支付订单" aria-label="Permalink to &quot;3.2 支付订单&quot;">​</a></h3><p>对应 [支付管理 -&gt; 支付订单] 菜单，进行支付订单的查看。如下图所示：</p><p><img src="'+b+'" alt="支付订单"></p><p>一般情况下，每个业务订单对应一条支付订单，保存在 <code>pay_order</code> 表，通过 <code>merchant_order_id</code> 字段关联。</p><h3 id="_3-3-退款订单" tabindex="-1">3.3 退款订单 <a class="header-anchor" href="#_3-3-退款订单" aria-label="Permalink to &quot;3.3 退款订单&quot;">​</a></h3><p>对应 [支付管理 -&gt; 退款订单] 菜单，进行退款订单的查看。如下图所示：</p><p><img src="'+f+'" alt="退款订单"></p><p>一般情况下，每个业务退款对应一条退款订单，保存在 <code>pay_refund</code> 表，通过 <code>merchant_refund_id</code> 字段关联。</p><h3 id="_3-4-回调通知" tabindex="-1">3.4 回调通知 <a class="header-anchor" href="#_3-4-回调通知" aria-label="Permalink to &quot;3.4 回调通知&quot;">​</a></h3><p>对应 [支付管理 -&gt; 回调通知] 菜单，查看支付、退款的回调业务的结果。如下图所示：</p><p><img src="'+g+'" alt="回调通知"></p><h3 id="_3-5-支付回调【重要】" tabindex="-1">3.5 支付回调【重要】 <a class="header-anchor" href="#_3-5-支付回调【重要】" aria-label="Permalink to &quot;3.5 支付回调【重要】&quot;">​</a></h3><p>这里，我们要配置支付【<strong>中心</strong>】提供给支付【<strong>渠道</strong>】的回调地址，不同于上面支付【<strong>应用</strong>】的回调地址。整体的回调关系如下图所示：</p><p><img src="'+E+'" alt="回调流程"></p><p>① 由于支付回调需要外网，可参考 <a href="./../natapp">《内网穿透》</a> 文档，将本地的 48080 端口，转发到外网中。这里，我的域名是 <code>http://yunai.natapp1.cc</code>。</p><p>② 在 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-server/src/main/resources/application-local.yaml#L196-L197" target="_blank" rel="noreferrer"><code>application-local.yaml</code></a> 配置文件中，修改 <code>yudao.pay</code> 配置项，设置为支付【中心】的回调地址。如下图所示：</p><p><img src="'+A+'" alt="配置回调地址"></p><ul><li><code>yudao.pay.order-notify-url</code> 配置项：对应 PayNotifyController 的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-pay/src/main/java/cn/iocoder/yudao/module/pay/controller/admin/notify/PayNotifyController.java#L59-L98" target="_blank" rel="noreferrer"><code>#notifyOrder(...)</code></a> 方法</li><li><code>yudao.pay.refund-notify-url</code> 配置项：对应 PayNotifyController 的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-pay/src/main/java/cn/iocoder/yudao/module/pay/controller/admin/notify/PayNotifyController.java#L59-L98" target="_blank" rel="noreferrer"><code>#notifyRefund(...)</code></a> 方法</li><li><code>yudao.pay.transfer-notify-url</code> 配置项：对应 PayNotifyController 的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-pay/src/main/java/cn/iocoder/yudao/module/pay/controller/admin/notify/PayNotifyController.java#L107-L127" target="_blank" rel="noreferrer"><code>#notifyTransfer(...)</code></a> 方法</li></ul><p>如果你想理解的更深入，可以后续 debug 断条调试。</p><h3 id="_3-6-接入示例" tabindex="-1">3.6 接入示例 <a class="header-anchor" href="#_3-6-接入示例" aria-label="Permalink to &quot;3.6 接入示例&quot;">​</a></h3><p>对应 [支付管理 -&gt; 接入示例 -&gt; 支付&amp;退款案例] 菜单，提供一个支付、退款的接入示例。如下图所示：</p><p><img src="'+B+'" alt="支付&amp;退款案例"></p><p>详细说明，可见如下文档：</p><ul><li><a href="./alipay-pay-demo">《支付宝支付接入》</a></li><li><a href="./refund-demo">《支付宝、微信退款接入》</a></li></ul><hr><p>对应 [支付管理 -&gt; 接入示例 -&gt; 提现转账案例] 菜单，提供一个转账的接入示例。如下图所示：</p><p><img src="'+o+'" alt="提现转账案例"></p><p>详细说明，可见如下文档：</p><ul><li><a href="./alipay-transfer-demo">《支付宝转账接入》</a></li><li><a href="./wx-transfer-demo">《微信转账接入》</a></li></ul><h3 id="_3-7-钱包充值、支付、退款" tabindex="-1">3.7 钱包充值、支付、退款 <a class="header-anchor" href="#_3-7-钱包充值、支付、退款" aria-label="Permalink to &quot;3.7 钱包充值、支付、退款&quot;">​</a></h3><p>详细可见 <a href="./wallet">《钱包充值、支付、退款》</a> 文档</p><h3 id="_3-8-模拟支付、退款" tabindex="-1">3.8 模拟支付、退款 <a class="header-anchor" href="#_3-8-模拟支付、退款" aria-label="Permalink to &quot;3.8 模拟支付、退款&quot;">​</a></h3><p>详细可见 <a href="./mock">《模拟支付、退款》</a> 文档</p><h3 id="_3-9-转账订单" tabindex="-1">3.9 转账订单 <a class="header-anchor" href="#_3-9-转账订单" aria-label="Permalink to &quot;3.9 转账订单&quot;">​</a></h3><p>对应 [支付管理 -&gt; 转账订单] 菜单，进行转账订单的查看。如下图所示：</p><p><img src="'+v+'" alt="退款订单"></p><p>一般情况下，每个业务提现（例如说：分销提现）对应一条转账订单，保存在 <code>pay_transfer</code> 表，通过 <code>merchant_transfer_id</code> 字段关联。</p>',88)])])}const Y=r(k,[["render",x]]);export{S as __pageData,Y as default};
